// src/mint.js
import { createUmi } from '@metaplex-foundation/umi-bundle-defaults';
import { publicKey } from '@metaplex-foundation/umi';
import { mplCandyMachine, fetchCandyMachine, mintV2 } from '@metaplex-foundation/mpl-candy-machine';
import * as cg from '@metaplex-foundation/mpl-candy-guard'; // CJS/ESM-safe import
const mplCandyGuard = cg.mplCandyGuard || (cg.default && cg.default.mplCandyGuard);
import { walletAdapterIdentity } from '@metaplex-foundation/umi-signer-wallet-adapters';
import { PhantomWalletAdapter } from '@solana/wallet-adapter-phantom';

const RPC = 'https://api.mainnet-beta.solana.com';
const CANDY_MACHINE = publicKey('CiYSyWyGd9hrV52916jdzj4TcLRezHY34KCaBZ7EjKSd');
const CANDY_GUARD   = publicKey('9m94QDkzsEoJLdfHMpyQUCgdS6fXSP1AeoEzf4RLmcUv');

const umi = createUmi(RPC).use(mplCandyMachine()).use(mplCandyGuard());

let adapter;

function log(msg) {
  const el = document.getElementById('log');
  if (!el) return;
  el.textContent = (msg + '\n' + el.textContent).slice(0, 5000);
}

async function connect() {
  try {
    adapter = new PhantomWalletAdapter();
    await adapter.connect();
    umi.use(walletAdapterIdentity(adapter));
    document.getElementById('connectBtn')?.classList.add('connected');
    log('🔗 Connected: ' + adapter.publicKey.toBase58());
  } catch (e) {
    console.error(e); log('❌ Connect failed: ' + (e.message || e));
  }
}

async function refreshSupply() {
  try {
    const cm = await fetchCandyMachine(umi, CANDY_MACHINE);
    const total = Number(cm.data.itemsAvailable);
    const left  = total - Number(cm.itemsRedeemed);
    const el = document.getElementById('supply');
    if (el) el.textContent = `${left} / ${total}`;
    log('ℹ️ Supply: ' + left + ' left');
  } catch (e) {
    console.error(e); log('⚠️ Supply check: ' + (e.message || e));
  }
}

async function mint() {
  try {
    if (!adapter || !adapter.connected) await connect();
    log('⛏️ Minten…');
    await mintV2(umi, {
      candyMachine: CANDY_MACHINE,
      candyGuard:   CANDY_GUARD,
      mintArgs: { mintLimit: { id: 1 } }, // jouw guard runtime arg
    }).sendAndConfirm(umi);
    log('✅ Mint gelukt! Check je wallet.');
    await refreshSupply();
  } catch (e) {
    console.error(e); log('❌ Mint failed: ' + (e.message || e));
  }
}

// Expose voor HTML-knoppen
window.MintApp = { connect, mint, refreshSupply };
document.addEventListener('DOMContentLoaded', refreshSupply);
